svg.script:
// 
async function loadWebpage() {
  const rootElement = document.getElementById('webpage-root');
  const targetUrl = 'https://raw.githubusercontent.com/UnblockingHub/UBHub/main/index.html';

  try {
    const response = await fetch(targetUrl);
    if (!response.ok) throw new Error(`HTTP error! Status: ${response.status}`);

    const htmlText = await response.text();

    // Convert the fetched raw text strings securely into HTML Nodes
    const parser = new DOMParser();
    const doc = parser.parseFromString(htmlText, 'text/html');

    // Clear out the "Loading..." placeholder text safely
    rootElement.innerHTML = '';

    // Move over scripts, links, styles, and body elements from the fetched page
    if (doc.head) {
      Array.from(doc.head.childNodes).forEach(node => {
        rootElement.appendChild(document.importNode(node, true));
      });
    }
    if (doc.body) {
      Array.from(doc.body.childNodes).forEach(node => {
        rootElement.appendChild(document.importNode(node, true));
      });
    }

  } catch (error) {
    rootElement.innerHTML = `<div style="color:red; font-family:sans-serif; padding:20px;">
      <h3>Failed to load application</h3>
      <p>${error.message}</p>
    </div>`;
  }
}

// Initialize the application after the SVG DOM sets up
document.addEventListener("DOMContentLoaded", loadWebpage);
//
